function songGen(theme, mood, rng){
  theme=String(theme||'').trim(); if(!theme) return {error:'请填写主题'};
  rng=rng||Math.random; mood=mood||'抒情';
  var v1=['窗外的 '+theme+' 轻轻落','我把 '+theme+' 写成了歌',''+theme+' 在掌心慢慢化','夜色里 '+theme+' 微亮'];
  var v2=['风吹过 '+theme+' 的轮廓',''+theme+' 是未说完的歌','把 '+theme+' 藏进口袋里',''+theme+' 陪我走过雨季'];
  var ch=['副歌：'+theme+'，啊 '+theme+'，是我唱给世界的温柔','副歌：就算时光走远，'+theme+' 还在心口'];
  function pick(a){ return a[Math.floor(rng()*a.length)]; }
  var lines=[pick(v1),pick(v2),pick(v1),'— 副歌 —',pick(ch),pick(ch)];
  return {lines:lines, theme:theme, mood:mood};
}
var EXPORTS={songGen:songGen};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SongForgePure = EXPORTS; }
